insert into rules (slug, rule_topic_id, scope_type, governing_body_id, applies_to) values ('fhsaa-nil-allowed', (select id from rule_topics where slug = 'nil-allowed'), 'governing_body', (select id from governing_bodies where slug = 'fhsaa'), 'high_school');
insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, effective_note, verification_status, trust_state, review_method, quick_status, short_answer) values ((select id from rules where slug = 'fhsaa-nil-allowed'), 1, 'yes_with_conditions', 'Yes. FHSAA athletes may profit from their name, image and likeness as long as they follow Bylaw 9.10.', 'Every other row in this matrix is one of those conditions.', 'FHSAA Bylaw 9.10.4 (numbered 9.9.4 before 2026-27)', 'First approved by the FHSAA Board on June 4, 2024. The 2026-27 Handbook, which states "These Bylaws are applicable to the 2026-27 school year", carries the same rules as Bylaw 9.10. A clarifying amendment (the word "Defined" added to the NIL collectives subtitle) was on the State Board of Education consent agenda on July 22, 2026, effective July 1, 2026. The State Board vote record was not located.', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'visual_source_check', 'YES', 'Yes. Every deal has to follow FHSAA Bylaw 9.10.');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fhsaa-nil-allowed' and v.is_current), (select id from sources where slug = 'fhsaa-bylaw-9-9-sbe-2024'), 'Bylaw 9.9.4', 'A student-athlete may profit from the use of their Name, Image, and Likeness subject to their compliance with FHSAA Bylaw 9.9.', 'visual_source_check', '2026-10-03', 'Claude (automated source research)');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fhsaa-nil-allowed' and v.is_current), (select id from sources where slug = 'fhsaa-letter-2024-06-21'), 'Letter, first paragraph', 'On June 4, 2024, the Florida High School Athletic Association''s (FHSAA) Board of Directors unanimously approved the revision of FHSAA Bylaw 9.9, Amateurism, to include Name, Image, and Likeness (NIL)', 'machine_extracted', '2026-10-03', 'Claude (automated source research)');
