insert into rule_versions (rule_id, version_no, answer, summary, citation, verification_status, trust_state, review_method) values ((select id from rules where slug = 'fhsaa-prohibited-categories'), 1, 'no', 'Nine categories are off limits for Florida high school athletes, listed in Bylaw 9.10.4.4 (a) through (i).', 'FHSAA Bylaw 9.10.4.4 (a)-(i)', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'visual_source_check');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fhsaa-prohibited-categories' and v.is_current), (select id from sources where slug = 'fhsaa-bylaw-9-9-sbe-2024'), 'Bylaw 9.9.4.4', 'Student-athletes are prohibited from engaging in any NIL activities involving the following categories of products and services: (a) Adult entertainment products and services; (b) Alcohol, tobacco, vaping, and nicotine products; (c) Cannabis products; (d) Controlled substances; (e) Prescription pharmaceuticals; (f) Gambling, including sports betting, the lottery, and betting in connection with video games, online games, and mobile devices; (g) Weapons, firearms, and ammunition; (h) Political or social activism; and (i) NIL Collectives.', 'visual_source_check', '2026-10-03', 'Claude (automated source research)');
