insert into rule_versions (rule_id, version_no, answer, summary, citation, verification_status, trust_state, review_method) values ((select id from rules where slug = 'fhsaa-collectives'), 1, 'no', 'No. NIL collectives are a prohibited category. The bylaw describes them as groups that collect funds from donors, individuals or businesses to facilitate NIL deals, pay or transfer funds to athletes, create ways for athletes to monetize their NIL, or otherwise promote NIL. School sanctioned team fundraising does not count as a collective.', 'FHSAA Bylaw 9.10.4.2 and 9.10.4.4(i)', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'visual_source_check');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fhsaa-collectives' and v.is_current), (select id from sources where slug = 'fhsaa-bylaw-9-9-sbe-2024'), 'Bylaw 9.9.4.2', 'NIL Collectives include but are not limited to, groups, organizations, or cooperative enterprises that exist to collect funds from donors, individuals, or businesses to: (a) help facilitate NIL deals for student-athletes; (b) facilitate payments to or transfers funds to student-athletes; (c) create ways for athletes to monetize from their NIL; and/or (d) otherwise promote NIL for schools or student-athletes. NIL Collectives shall not include school sanctioned team fundraising.', 'visual_source_check', '2026-10-03', 'Claude (automated source research)');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fhsaa-collectives' and v.is_current), (select id from sources where slug = 'fhsaa-handbook-2026-27'), 'Bylaw 9.10 (numbered 9.9 before 2026-27), pages 30 to 31', NULL, 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
