insert into rules (slug, rule_topic_id, scope_type, governing_body_id, applies_to) values ('fhsaa-agents', (select id from rule_topics where slug = 'agents'), 'governing_body', (select id from governing_bodies where slug = 'fhsaa'), 'high_school');
insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status, trust_state, review_method, quick_status, short_answer) values ((select id from rules where slug = 'fhsaa-agents'), 1, 'yes_with_conditions', 'Only for NIL advice. Hiring a registered agent to manage an athletic career can cost amateur status, except when the agent is hired to advise on NIL related matters.', 'The bylaw does not define "registered agent". Florida athlete agent licensing rules were not checked for high school athletes.', 'FHSAA Bylaw 9.10.2(d)', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'visual_source_check', 'DEPENDS', 'Only to advise on NIL. An agent who manages your athletic career can cost you amateur status.');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fhsaa-agents' and v.is_current), (select id from sources where slug = 'fhsaa-bylaw-9-9-sbe-2024'), 'Bylaw 9.9.2(d)', 'd) Signing a professional playing contract in any sport or hiring a registered agent to manage his/her athletic career, other than for the purpose of advising on NIL related matters;', 'visual_source_check', '2026-10-03', 'Claude (automated source research)');
