insert into rules (slug, rule_topic_id, scope_type, governing_body_id, applies_to) values ('fhsaa-transfers', (select id from rule_topics where slug = 'transfers'), 'governing_body', (select id from governing_bodies where slug = 'fhsaa'), 'high_school');
insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status, trust_state, review_method) values ((select id from rules where slug = 'fhsaa-transfers'), 1, 'no', 'Not that season. An athlete who transfers after starting a sport cannot secure an NIL agreement that season, unless one of the exceptions in Bylaw 9.3.2.2 applies.', 'The exceptions in Bylaw 9.3.2.2 include a military move, foster care placement, a court-ordered change in custody, a full and complete move, and reassignment by the district school board. The transfer bylaw was substantively amended for 2026-27, so ask your athletic director whether one applies to you.', 'FHSAA Bylaw 9.10.4.7', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'visual_source_check');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fhsaa-transfers' and v.is_current), (select id from sources where slug = 'fhsaa-bylaw-9-9-sbe-2024'), 'Bylaw 9.9.4.7', 'A student-athlete who transfers after starting a sport, shall be prohibited from securing an NIL agreement that season, unless he/she meets one of the provisions outlined in Bylaw 9.3.2.2.', 'visual_source_check', '2026-10-03', 'Claude (automated source research)');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fhsaa-transfers' and v.is_current), (select id from sources where slug = 'fhsaa-handbook-2026-27'), 'Bylaw 9.10 (numbered 9.9 before 2026-27), pages 30 to 31', NULL, 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
