insert into rules (slug, rule_topic_id, scope_type, state_id, applies_to) values ('fl-hs-no-statute', (select id from rule_topics where slug = 'nil-allowed'), 'state', (select id from states where code = 'FL'), 'high_school');
insert into rule_versions (rule_id, version_no, answer, summary, citation, verification_status, trust_state, review_method, review_note) values ((select id from rules where slug = 'fl-hs-no-statute'), 1, 'not_addressed', 'We found no Florida statute on high school NIL. Section 1006.20(2)(a) requires FHSAA bylaw changes to be ratified by the State Board of Education, so the FHSAA bylaw is the rule we cite.', 'Section 1006.20(2)(a), Florida Statutes', 'researched', 'PUBLIC_POLICY_NOT_LOCATED', 'raw_source_text', 'No Florida statute on high school NIL was located. Section 1006.20 was read; it leaves eligibility to FHSAA bylaws.');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fl-hs-no-statute' and v.is_current), (select id from sources where slug = 'fl-stat-1006-20'), 's. 1006.20(2)(a)', 'Any changes to the FHSAA''s bylaws must be ratified by the State Board of Education.', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
insert into verification_events (entity_type, entity_id, status, method, verified_on, verified_by, notes) values ('rule_version', (select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fl-hs-no-statute' and v.is_current), 'PUBLIC_POLICY_NOT_LOCATED', 'automated_fetch', '2026-10-03', 'Claude (automated source research)', 'Full page text read from the official site by Claude. Not a human review.');
insert into rules (slug, rule_topic_id, scope_type, state_id, applies_to) values ('fl-college-nil-allowed', (select id from rule_topics where slug = 'nil-allowed'), 'state', (select id from states where code = 'FL'), 'college');
insert into rule_versions (rule_id, version_no, answer, summary, citation, effective_note, verification_status, trust_state, review_method, quick_status, short_answer) values ((select id from rules where slug = 'fl-college-nil-allowed'), 1, 'yes', 'Yes. In a legislative finding, section 1006.74 says a college athlete "must have an equal opportunity to control and profit from the commercial use of her or his name, image, or likeness." The current section has four subsections (definition, workshops, liability, rulemaking) and none restricts athlete deals.', 'Section 1006.74, Florida Statutes (opening paragraph)', 'Created in 2020 (effective July 1, 2021) and revised by HB 7-B, effective February 16, 2023.', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text', 'YES', 'Yes. Florida law says college athletes must have an equal opportunity to profit from their NIL.');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fl-college-nil-allowed' and v.is_current), (select id from sources where slug = 'fl-stat-1006-74'), 's. 1006.74, opening paragraph', 'participation in intercollegiate athletics should not infringe upon an intercollegiate athlete''s ability to earn compensation for her or his name, image, or likeness. An intercollegiate athlete must have an equal opportunity to control and profit from the commercial use of her or his name, image, or likeness, and be protected from unauthorized appropriation and commercial exploitation of her or his right to publicity, including her or his name, image, or likeness.', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
insert into verification_events (entity_type, entity_id, status, method, verified_on, verified_by, notes) values ('rule_version', (select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fl-college-nil-allowed' and v.is_current), 'VERIFIED_TO_OFFICIAL_SOURCE', 'automated_fetch', '2026-10-03', 'Claude (automated source research)', 'Full page text read from the official site by Claude. Not a human review.');
insert into rules (slug, rule_topic_id, scope_type, state_id, applies_to) values ('fl-college-education', (select id from rule_topics where slug = 'nil-education'), 'state', (select id from states where code = 'FL'), 'college');
insert into rule_versions (rule_id, version_no, answer, summary, citation, verification_status, trust_state, review_method) values ((select id from rules where slug = 'fl-college-education'), 1, 'yes', 'Yes. Every covered Florida college must run at least two financial literacy, life skills and entrepreneurship workshops, each at least five hours, in different semesters, before an athlete graduates.', 'Section 1006.74(2), Florida Statutes; Board of Governors Regulation 6.022(1)', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fl-college-education' and v.is_current), (select id from sources where slug = 'fl-stat-1006-74'), 's. 1006.74(2)', 'A postsecondary educational institution must conduct at least two financial literacy, life skills, and entrepreneurship workshops, each for a minimum of 5 hours, before the graduation of an intercollegiate athlete. The workshops may not be identical, and the second workshop must include more rigorous instruction. The workshops may not be conducted in the same semester.', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fl-college-education' and v.is_current), (select id from sources where slug = 'bog-reg-6-022'), 'Regulation 6.022(1)', 'Each university must conduct at least two financial literacy, life skills, and entrepreneurship workshops for a minimum of five (5) hours each consistent with the requirements in section 1006.74, Florida Statutes, prior to the graduation of the intercollegiate athlete.', 'machine_extracted', '2026-10-03', 'Claude (automated source research)');
insert into verification_events (entity_type, entity_id, status, method, verified_on, verified_by, notes) values ('rule_version', (select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fl-college-education' and v.is_current), 'VERIFIED_TO_OFFICIAL_SOURCE', 'automated_fetch', '2026-10-03', 'Claude (automated source research)', 'Full page text read from the official site by Claude. Not a human review.');
insert into rules (slug, rule_topic_id, scope_type, state_id, applies_to) values ('fl-college-agents', (select id from rule_topics where slug = 'agents'), 'state', (select id from states where code = 'FL'), 'college');
insert into rule_versions (rule_id, version_no, answer, summary, citation, verification_status, trust_state, review_method, quick_status, short_answer) values ((select id from rules where slug = 'fl-college-agents'), 1, 'yes_with_conditions', 'Yes, but the agent must hold a Florida athlete agent license to represent a college athlete on NIL contracts. A spouse, parent, sibling, grandparent or guardian is not treated as an athlete agent.', 'Sections 468.453(8) and 468.452(2), Florida Statutes', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text', 'YES', 'Yes. The agent needs a Florida athlete agent license.');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fl-college-agents' and v.is_current), (select id from sources where slug = 'fl-stat-468-453'), 's. 468.453(8)', 'Notwithstanding subsection (3), a person must hold a valid license as an athlete agent to act as an athlete agent representing an intercollegiate athlete for purposes of contracts that allow an intercollegiate athlete to profit from the commercial use of her or his name, image, or likeness', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fl-college-agents' and v.is_current), (select id from sources where slug = 'fl-stat-468-452'), 's. 468.452(2)', 'The term does not include a spouse, parent, sibling, grandparent, or guardian of the student athlete or an individual acting solely on behalf of a professional sports team or professional sports organization.', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
insert into verification_events (entity_type, entity_id, status, method, verified_on, verified_by, notes) values ('rule_version', (select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fl-college-agents' and v.is_current), 'VERIFIED_TO_OFFICIAL_SOURCE', 'automated_fetch', '2026-10-03', 'Claude (automated source research)', 'Full page text read from the official site by Claude. Not a human review.');
insert into rules (slug, rule_topic_id, scope_type, state_id, applies_to) values ('fl-college-disclosure', (select id from rule_topics where slug = 'disclosure-required'), 'state', (select id from states where code = 'FL'), 'college');
insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status, trust_state, review_method, quick_status, short_answer) values ((select id from rules where slug = 'fl-college-disclosure'), 1, 'not_addressed', 'Florida''s NIL statute, section 1006.74, has no requirement to disclose NIL deals to the school. The deal-reporting duty comes from NCAA rules. Florida law does require notice of an agent contract: the agent must tell the athletic director within 72 hours of signing, or before the athlete''s next athletic event if that is sooner, and the athlete must also inform the school.', 'This notice is about signing with an athlete agent, not about each NIL deal.', 'Sections 1006.74 and 468.454(6) and (7), Florida Statutes', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text', 'NOT_PUBLICLY_SPECIFIED', 'Florida''s NIL statute has no disclosure rule. The NCAA rule is the one that applies.');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fl-college-disclosure' and v.is_current), (select id from sources where slug = 'fl-stat-1006-74'), 's. 1006.74(1)-(4)', '(4) The Board of Governors and the State Board of Education shall adopt regulations and rules, respectively, to implement this section.History.—s. 1, ch. 2020-28; s. 20, ch. 2021-35; ss. 1, 2, ch. 2021-217; s. 2, ch. 2023-4.', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fl-college-disclosure' and v.is_current), (select id from sources where slug = 'fl-stat-468-454'), 's. 468.454(6)', 'Within 72 hours after entering into an agent contract or before the next scheduled athletic event in which the student athlete may participate, whichever occurs first, the athlete agent must give notice in a record of the existence of the contract to the athletic director of the educational institution at which the student athlete is enrolled', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
insert into verification_events (entity_type, entity_id, status, method, verified_on, verified_by, notes) values ('rule_version', (select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fl-college-disclosure' and v.is_current), 'VERIFIED_TO_OFFICIAL_SOURCE', 'automated_fetch', '2026-10-03', 'Claude (automated source research)', 'Full page text read from the official site by Claude. Not a human review.');
insert into rules (slug, rule_topic_id, scope_type, governing_body_id, applies_to) values ('ncaa-nil-allowed', (select id from rule_topics where slug = 'nil-allowed'), 'governing_body', (select id from governing_bodies where slug = 'ncaa'), 'college');
insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, effective_date, verification_status, trust_state, review_method, quick_status, short_answer) values ((select id from rules where slug = 'ncaa-nil-allowed'), 1, 'yes_with_conditions', 'Yes. Division I athletes may be paid for the use of their name, image and likeness in third-party deals.', 'NIL cannot be payment for playing or for athletic achievement.', 'NCAA Division I Bylaws 22.01.1 and 22.1.2', '2025-07-01', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text', 'YES', 'Yes. Division I athletes can be paid by third parties for their NIL.');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'ncaa-nil-allowed' and v.is_current), (select id from sources where slug = 'ncaa-d1-manual-2026-27'), 'Bylaws 22.01.1, 22.1.2', 'An individual may receive compensation for the use of the individual’s name, image and likeness, which may be secured or compensated based, in whole or in part, on athletics skill or reputation. ... An individual may permit the use of the individual’s name, image, likeness in noninstitutional name, image and likeness activities and receive compensation for such activities.', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
insert into verification_events (entity_type, entity_id, status, method, verified_on, verified_by, notes) values ('rule_version', (select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'ncaa-nil-allowed' and v.is_current), 'VERIFIED_TO_OFFICIAL_SOURCE', 'automated_fetch', '2026-10-03', 'Claude (automated source research)', 'Full page text read from the official site by Claude. Not a human review.');
insert into rules (slug, rule_topic_id, scope_type, governing_body_id, applies_to) values ('ncaa-pay-for-play', (select id from rule_topics where slug = 'pay-for-play'), 'governing_body', (select id from governing_bodies where slug = 'ncaa'), 'college');
insert into rule_versions (rule_id, version_no, answer, summary, citation, effective_date, verification_status, trust_state, review_method) values ((select id from rules where slug = 'ncaa-pay-for-play'), 1, 'no', 'No. NIL activities may not be used to pay an athlete for athletics participation or achievement.', 'NCAA Division I Bylaw 22.01.1', '2025-07-01', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'ncaa-pay-for-play' and v.is_current), (select id from sources where slug = 'ncaa-d1-manual-2026-27'), 'Bylaw 22.01.1', 'Name, image and likeness activities may not be used to compensate an individual for athletics participation or achievement.', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
