insert into rules (slug, rule_topic_id, scope_type, governing_body_id, applies_to) values ('ncaa-school-payments', (select id from rule_topics where slug = 'school-payments'), 'governing_body', (select id from governing_bodies where slug = 'ncaa'), 'college');
insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status, trust_state, review_method) values ((select id from rules where slug = 'ncaa-school-payments'), 1, 'yes_with_conditions', 'Yes. NCAA rules let a school make direct payments to athletes within the annual benefits cap, and the College Sports Commission says schools can enter NIL deals directly with athletes. Those deals are reported by the school and do not go into NIL Go. Schools outside the ACC, Big Ten, Big 12, Pac-12 and SEC choose each year whether to opt in, so check what your school has announced.', 'The cap is about $21.58 million per school for 2026-27.', 'NCAA Division I Bylaw 16.13.1; CSC FAQ', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'ncaa-school-payments' and v.is_current), (select id from sources where slug = 'ncaa-d1-manual-2026-27'), 'Bylaw 16.13.1', 'An institution may provide direct payments, benefits and expenses to a student-athlete as specified in this section, provided the aggregate value provided by (or on behalf of) the institution does not exceed the value of the applicable period’s benefits cap and the written agreement does not provide for payments to a third party on a student-athlete’s behalf.', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'ncaa-school-payments' and v.is_current), (select id from sources where slug = 'csc-faq'), 'What is the revenue share cap?', 'The cap for the 2026-27 academic year is approximately $21.58 million per school, up from $20.5 million during the 2025-26 academic year. ... Yes. Those deals are reported by the school via the CAPS platform and subject to the revenue sharing cap. ... Payment directly from the student-athlete’s institution is not considered a third-party NIL deal and does not need to be reported in NIL Go.', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'ncaa-school-payments' and v.is_current), (select id from sources where slug = 'csc-faq'), 'What is the process for a school opting in or out of revenue sharing?', 'Each year, schools outside of the ACC, Big Ten, Big 12, Pac-12 and SEC will have the option to opt in to or out of revenue sharing.', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
insert into verification_events (entity_type, entity_id, status, method, verified_on, verified_by, notes) values ('rule_version', (select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'ncaa-school-payments' and v.is_current), 'VERIFIED_TO_OFFICIAL_SOURCE', 'automated_fetch', '2026-10-03', 'Claude (automated source research)', 'Full page text read from the official site by Claude. Not a human review.');
insert into rules (slug, rule_topic_id, scope_type, governing_body_id, applies_to) values ('ncaa-school-staff', (select id from rule_topics where slug = 'school-staff-involvement'), 'governing_body', (select id from governing_bodies where slug = 'ncaa'), 'college');
insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status, trust_state, review_method, quick_status, short_answer) values ((select id from rules where slug = 'ncaa-school-staff'), 1, 'yes_with_conditions', 'Yes, within limits. A school may act as a marketing agent for an athlete on third-party NIL deals. A school may not guarantee a third-party deal, and the payor must attest that the school did not direct it to make the deal and that it funded the payment itself.', 'A June 2025 NCAA question and answer document adds that a school may help identify or facilitate a deal when the third party funds the whole payment. That document predates the current Manual.', 'NCAA Division I Bylaws 22.1.1, 22.1.1.1 and 22.2.3', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text', 'DEPENDS', 'A school may help find or facilitate a deal that a third party fully funds. It may not guarantee one.');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'ncaa-school-staff' and v.is_current), (select id from sources where slug = 'ncaa-d1-manual-2026-27'), 'Bylaws 22.1.1(b), 22.1.1.1', 'Act as a marketing agent for a student-athlete with respect to noninstitutional name, image or likeness contracts. ... An institution shall not provide a written or oral guarantee of a third-party NIL contract or payment. ... (c) That the noninstitutional payor was not directed by an institution to enter into the contract or payment terms with the student-athlete; and (d) That the noninstitutional payor has self-funded the payment to the student-athlete.', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'ncaa-school-staff' and v.is_current), (select id from sources where slug = 'ncaa-house-qa-2025-06'), 'Question E3', 'Yes, provided the third party is self-funding the entire payment outlined in the NIL contract.', 'machine_extracted', '2026-10-03', 'Claude (automated source research)');
insert into verification_events (entity_type, entity_id, status, method, verified_on, verified_by, notes) values ('rule_version', (select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'ncaa-school-staff' and v.is_current), 'VERIFIED_TO_OFFICIAL_SOURCE', 'automated_fetch', '2026-10-03', 'Claude (automated source research)', 'Full page text read from the official site by Claude. Not a human review.');
insert into rules (slug, rule_topic_id, scope_type, governing_body_id, applies_to) values ('ncaa-collectives', (select id from rule_topics where slug = 'collectives'), 'governing_body', (select id from governing_bodies where slug = 'ncaa'), 'college');
insert into rule_versions (rule_id, version_no, answer, summary, citation, verification_status, trust_state, review_method) values ((select id from rules where slug = 'ncaa-collectives'), 1, 'yes_with_conditions', 'Yes, but deals with a collective or any other "associated entity" must be for a valid business purpose (promoting goods or services sold to the public for profit), at rates in line with what similarly situated people with comparable NIL value, who are not athletes or recruits of that school, are paid. Raising money to induce athletes to attend a school does not qualify.', 'NCAA Division I Bylaws 22.02.1 and 22.1.3', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'ncaa-collectives' and v.is_current), (select id from sources where slug = 'ncaa-d1-manual-2026-27'), 'Bylaw 22.1.3', 'An associated entity or individual shall not enter into an agreement with or provide payment to a prospective student-athlete or student-athlete unless the agreement or payment terms, as determined by the name, image and likeness clearinghouse, are for a valid business purpose related to the promotion or endorsement of goods or services provided to the general public for profit, with compensation at rates and terms commensurate with compensation paid to similarly situated individuals with comparable name, image and likeness value who are not prospective student-athletes or student-athletes of the institution. Raising money to induce student-athletes to attend or participate in intercollegiate athletics at an institution does not satisfy the valid business purpose requirement for making NIL payments to student-athletes.', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
insert into verification_events (entity_type, entity_id, status, method, verified_on, verified_by, notes) values ('rule_version', (select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'ncaa-collectives' and v.is_current), 'VERIFIED_TO_OFFICIAL_SOURCE', 'automated_fetch', '2026-10-03', 'Claude (automated source research)', 'Full page text read from the official site by Claude. Not a human review.');
insert into rules (slug, rule_topic_id, scope_type, governing_body_id, applies_to) values ('ncaa-boosters', (select id from rule_topics where slug = 'boosters'), 'governing_body', (select id from governing_bodies where slug = 'ncaa'), 'college');
insert into rule_versions (rule_id, version_no, answer, summary, citation, verification_status, trust_state, review_method, quick_status, short_answer) values ((select id from rules where slug = 'ncaa-boosters'), 1, 'yes_with_conditions', 'Yes, with review. Anyone who has given more than $50,000 in their lifetime to the school or its collective is an "associated individual", so deals with them face the valid business purpose and compensation tests.', 'NCAA Division I Bylaws 22.02.2 and 22.1.3', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text', 'DEPENDS', 'Yes, but deals with major donors get extra review in NIL Go.');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'ncaa-boosters' and v.is_current), (select id from sources where slug = 'ncaa-d1-manual-2026-27'), 'Bylaw 22.02.2(b)', 'An individual who directly or indirectly (including contributions by an affiliated entity or family member) has contributed more than $50,000 during the individual’s lifetime to an institution or to an associated entity defined in 22.02.1-(a)', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
