insert into rules (slug, rule_topic_id, scope_type, governing_body_id, applies_to) values ('ncaa-logos-marks', (select id from rule_topics where slug = 'school-logos-marks'), 'governing_body', (select id from governing_bodies where slug = 'ncaa'), 'college');
insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status, trust_state, review_method, quick_status, short_answer) values ((select id from rules where slug = 'ncaa-logos-marks'), 1, 'not_addressed', 'NCAA Bylaws 22.01 through 22.3 say nothing about athletes using school logos or marks in third-party deals, so your school''s policy decides. The NCAA tells athletes to "Review your campus NIL policy and applicable state law."', 'Bylaw 22.4 is a separate rule that limits commercial logos on uniforms and equipment worn in competition.', 'NCAA Division I Manual 2026-27, Article 22 (no provision on school marks in NIL deals)', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text', 'NOT_PUBLICLY_SPECIFIED', 'NCAA rules do not cover this. Your school sets it.');
