insert into rule_versions (rule_id, version_no, answer, summary, citation, verification_status, trust_state, review_method) values ((select id from rules where slug = 'ncaa-transfers'), 1, 'yes_with_conditions', 'Four-year transfers must report deals of $600 or more signed from the date they entered the Transfer Portal. A deal that was already cleared and stays in place does not need to be resubmitted.', 'NCAA Division I Bylaw 22.2.2.5.2', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'ncaa-transfers' and v.is_current), (select id from sources where slug = 'ncaa-d1-manual-2026-27'), 'Bylaw 22.2.2.5.2', 'Prospective four-year college transfers shall report all noninstitutional name, image, and likeness contracts or payment terms with compensation of $600 or more that have been executed from the date in which the student-athlete’s name was officially entered into the NCAA Transfer Portal. A transfer who has previously reported a deal that will remain in place upon transfer shall not be required to resubmit the deal if it has been cleared by the CSC.', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
