insert into rule_versions (rule_id, version_no, answer, summary, citation, verification_status, trust_state, review_method) values ((select id from rules where slug = 'csc-international'), 1, 'yes_with_conditions', 'International athletes must report deals of $600 or more like every Division I athlete, but whether a deal is legal for them can depend on immigration rules. The College Sports Commission tells them to consult their school before going ahead.', 'CSC FAQ, "Are international student-athletes required to report third-party NIL deals?"', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'csc-international' and v.is_current), (select id from sources where slug = 'csc-faq'), 'International student-athletes', 'All Division I student-athletes are required to report their third-party NIL deals at or above $600 in aggregate in NIL Go. However, the legality of such deals may vary depending on factors including state and federal laws and immigration regulations. Student-athletes should reach out to their institution for guidance and consult with them before proceeding with any third-party NIL deals.', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
