insert into rule_versions (rule_id, version_no, answer, summary, citation, verification_status, trust_state, review_method, quick_status, short_answer) values ((select id from rules where slug = 'uf-logos-marks'), 1, 'only_with_approval', 'Only with approval. UF says you can use the Gator logo, marks and colors for marketing purposes if you have approval, and to avoid showing UF logos or team trademarks in ads unless you have it. UF lists its Licensing Manager as the contact for merchandise, apparel and logo questions.', 'UF, Overview of Gators NIL; UAA Licensing FAQ', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text', 'CHECK_FIRST', 'Only with UF''s approval.');
