insert into rule_versions (rule_id, version_no, answer, summary, citation, verification_status, trust_state, review_method) values ((select id from rules where slug = 'uf-team-activities'), 1, 'only_with_approval', 'During official team activities (games, practices, team travel) UF says to stick to team-approved gear and appearances. A deal with a brand other than the team sponsors is fine, but do not wear or promote that brand''s gear at games or team practices.', 'UF, Overview of Gators NIL', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'uf-team-activities' and v.is_current), (select id from sources where slug = 'uf-nil-overview'), 'Team commitments', 'During official team activities (games, practices, team travel, etc.), stick to team-approved gear and appearances. For example, if you sign an apparel deal with a brand other than our team sponsors (Nike/Jordan), that’s okay – just don’t wear or promote that brand’s gear at Gator games or team practices.', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
