insert into rules (slug, rule_topic_id, scope_type, institution_id, applies_to) values ('uf-disclosure', (select id from rule_topics where slug = 'disclosure-required'), 'institution', (select id from institutions where slug = 'university-of-florida'), 'college');
insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status, trust_state, review_method, quick_status, short_answer) values ((select id from rules where slug = 'uf-disclosure'), 1, 'yes', 'UF repeats the national rule: any third-party deal worth $600 or more goes into NIL Go within five business days of signing. An agent or parent can enter it, but the athlete must hit submit.', 'A UF International Center page also mentions reporting NIL activity to UAA Compliance through a Teamworks form. That may predate NIL Go and needs confirmation.', 'UF, Overview of Gators NIL', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text', 'DEPENDS', 'Deals worth $600 or more go into NIL Go within five business days of signing.');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'uf-disclosure' and v.is_current), (select id from sources where slug = 'uf-nil-overview'), 'Reporting', 'Under the new House v. NCAA settlement, any third-party NIL contract or deal worth $600 or more (in total value) must be reported online through the NIL platform called NIL Go. ... within 5 business days of signing the contract ... You can do it yourself or have one trusted rep (like an agent or parent) enter the deal in NIL Go on your behalf – but you, the student-athlete, must hit ''submit''.', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
insert into disclosure_requirements (rule_version_id, what, recipient, deadline_text, deadline_business_days, threshold_usd, platform_name, platform_url) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'uf-disclosure' and v.is_current), 'Any third-party NIL deal worth $600 or more in total: who the sponsor is, what you will provide, how much you will be paid, and the contract', 'NIL Go (College Sports Commission)', 'Within five business days of signing', 5, 600, 'NIL Go', 'https://www.collegesportscommission.org/nil/');
