insert into rules (slug, rule_topic_id, scope_type, district_id, applies_to) values ('scps-facilities', (select id from rule_topics where slug = 'school-facilities'), 'district', (select id from school_districts where slug = 'seminole-county-public-schools'), 'high_school');
insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status, trust_state, review_method, quick_status, short_answer, nil_specific) values ((select id from rules where slug = 'scps-facilities'), 1, 'only_with_approval', 'Only through the district. Any outside use of a Seminole County Public Schools facility must be requested online through Facilitron, with payment and proof of insurance. District staff make the final decision.', 'Board Policy 7510 (revised 11/14/23) was read in full. It sets the request, fee and insurance process and does not mention filming, photography or commercial shoots. The district''s Facility Use Handbook was not read.', 'SCPS Facility Requests and Rental page', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text', 'CHECK_FIRST', 'Only through the district''s facility request process.', FALSE);
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'scps-facilities' and v.is_current), (select id from sources where slug = 'scps-facility-use'), 'Facility Requests/Rental', 'Moving forward, the only way to request use of a district facility is by creating a Facilitron account and submitting a request online. ... Facilitron will also collect payment and proof of insurance (certificate of insurance) on Seminole County Public Schools'' behalf. ... Seminole County Public Schools'' administrative staff will make final decisions on all facility use requests.', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'scps-facilities' and v.is_current), (select id from sources where slug = 'scps-policy-7510'), 'Policy 7510, whole policy', 'The required certificate of insurance must be provided seven (7) business days prior to the Facility use; failure to provide the required insurance may result in the cancellation of the Facility use.', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
insert into verification_events (entity_type, entity_id, status, method, verified_on, verified_by, notes) values ('rule_version', (select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'scps-facilities' and v.is_current), 'VERIFIED_TO_OFFICIAL_SOURCE', 'automated_fetch', '2026-10-03', 'Claude (automated source research)', 'Full page text read from the official site by Claude. Not a human review.');
insert into rules (slug, rule_topic_id, scope_type, institution_id, applies_to) values ('shs-event-footage', (select id from rule_topics where slug = 'event-footage'), 'institution', (select id from institutions where slug = 'seminole-high-school-sanford'), 'high_school');
insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status, trust_state, review_method, nil_specific) values ((select id from rules where slug = 'shs-event-footage'), 1, 'only_with_approval', 'Only with written approval. Seminole High School''s media credential terms prohibit secondary or commercial use of pictures, audio or film of its athletics events made by a credential holder, including advertising and sales promotion, without prior specific written approval of Seminole High School Athletics. Separately, FHSAA Bylaw 9.10.4.3 bars referring to a member school event or game in NIL activity.', 'These terms bind credentialed media. The page does not address footage shot by families or the athlete.', 'Seminole High School Athletics, Media Credential Request terms', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text', FALSE);
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'shs-event-footage' and v.is_current), (select id from sources where slug = 'shs-media-credentials'), 'Media Credential Request, use of coverage', 'Any secondary or commercial use of any picture, audio description, film/tape, or drawing of any Seminole High School Athletics Events taken or made by the Credential Holder (including, but not limited to use in delayed editorial, advertising, sales promotion, or merchandising) is prohibited without prior specific written approval of Seminole High School Athletics.', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
