insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status, trust_state, review_method, quick_status, short_answer) values ((select id from rules where slug = 'american-school-payments'), 1, 'yes', 'The American says it was the first conference to set league-wide minimum investment and revenue sharing protocols for member schools to give financial benefits to athletes.', 'The conference''s About page gives no amounts or terms. News reports describe the size and timing of the minimum and say Army and Navy are excluded. The official release with the terms was not located.', 'American Conference About page', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text', 'YES', 'The American sets a league-wide minimum for sharing revenue with athletes.');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'american-school-payments' and v.is_current), (select id from sources where slug = 'american-c1'), 'About', 'The American became the first conference to establish league-wide minimum investment and revenue sharing protocols to provide financial benefits to student-athletes.', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
