insert into rules (slug, rule_topic_id, scope_type, institution_id, applies_to) values ('fsu-disclosure-required', (select id from rule_topics where slug = 'disclosure-required'), 'institution', (select id from institutions where slug = 'florida-state-university'), 'college');
insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status, trust_state, review_method, quick_status, short_answer) values ((select id from rules where slug = 'fsu-disclosure-required'), 1, 'yes', 'FSU says athletes must disclose third-party NIL deals worth $600 or more in NIL Go within 5 business days of execution.', 'This matches the national rule. The FSU page adds that deals with the same sponsor count together toward $600 and warns that failure to disclose may cost eligibility.', 'FSU Compliance page, NIL Disclosure via NILGO', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text', 'YES', 'Report deals of $600 or more in NIL Go within 5 business days.');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fsu-disclosure-required' and v.is_current), (select id from sources where slug = 'fsu-s1'), 'NIL Disclosure via NILGO', 'Any NIL deals involving third parties worth $600 or more must be disclosed by the student-athlete in NIL Go within 5 business days of execution.', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fsu-disclosure-required' and v.is_current), (select id from sources where slug = 'fsu-s1'), 'NIL Disclosure via NILGO', 'Failure to disclose may lead to penalties, including the loss of NCAA eligibility.', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
insert into disclosure_requirements (rule_version_id, what, recipient, deadline_text, platform_name, platform_url, form_name, form_url) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fsu-disclosure-required' and v.is_current), 'Third-party NIL deals worth $600 or more, including cash, non-cash benefits and deals that could exceed $600', 'NIL Go (the athlete enters the deal)', 'within 5 business days of execution', 'NIL Go', 'https://help.nilgo.com/en/', NULL, NULL);
