insert into rules (slug, rule_topic_id, scope_type, institution_id, applies_to) values ('fsu-agents', (select id from rule_topics where slug = 'agents'), 'institution', (select id from institutions where slug = 'florida-state-university'), 'college');
insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status, trust_state, review_method, quick_status, short_answer) values ((select id from rules where slug = 'fsu-agents'), 1, 'only_with_approval', 'FSU says every agent must register with FSU before contacting an FSU athlete about NIL or pro sports. This is on top of state, NCAA and players association rules. FSU says an athlete or parent may contact an agent, but the athlete must tell the FSU Athletics Compliance Office before the first contact. Agents who write to athletes must send a copy to the Compliance Office.', 'For NIL only, FSU says an agent may be registered with the State of Florida. Agents not registered with FSU must complete registration in seven business days.', 'FSU Compliance page, Agents & Advisors; FSU Compliance page, Contact Between Registered Agents and Student-Athletes', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text', 'CHECK_FIRST', 'Agents must register with FSU first.');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fsu-agents' and v.is_current), (select id from sources where slug = 'fsu-s1'), 'Agents & Advisors', 'all agents must be registered with Florida State University (FSU) in addition to the requirements established by the State of Florida, the NCAA, and the applicable professional association.', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fsu-agents' and v.is_current), (select id from sources where slug = 'fsu-s1'), 'FSU Agent Registration', 'To register with FSU, please complete the online Agent Registration Form.', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fsu-agents' and v.is_current), (select id from sources where slug = 'fsu-s1'), 'Contact Between Non-Registered Agents and Student-Athletes', 'All non-FSU registered agents must complete the registration in seven business days.', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fsu-agents' and v.is_current), (select id from sources where slug = 'fsu-s1'), 'Student-Athlete Initiating Contact', 'provided the student-athlete notifies FSU Athletics Compliance Office prior to initiating contact for the first time.', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fsu-agents' and v.is_current), (select id from sources where slug = 'fsu-s1'), 'Agent Initiating Contact', 'FSU permits athlete agents to send correspondence regarding their services to student-athletes provided a copy of such correspondence is also submitted to FSU Athletics Compliances Office.', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
